CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, singleton boolean NOT NULL DEFAULT true UNIQUE CHECK(singleton), email text NOT NULL UNIQUE, password_hash text NOT NULL, profile jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS data_generation integer NOT NULL DEFAULT 0 CHECK(data_generation >= 0);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_throttle(key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS logs(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, kind text NOT NULL, date date NOT NULL, occurred_at timestamptz NOT NULL, source text NOT NULL CHECK(source IN ('manual','apple-health')), health_key text, external_id text, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS logs_user_date ON logs(user_id,date DESC);
CREATE UNIQUE INDEX IF NOT EXISTS logs_health_day ON logs(user_id,source,health_key,date) WHERE health_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS health_external_ids(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, external_id text NOT NULL, metric text NOT NULL, date date NOT NULL, PRIMARY KEY(user_id,external_id,metric));
CREATE TABLE IF NOT EXISTS focus_sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,category text NOT NULL,status text NOT NULL CHECK(status IN ('running','paused','finished')),intervals jsonb NOT NULL,version integer NOT NULL DEFAULT 0,corrected_minutes numeric,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS focus_one_active ON focus_sessions(user_id) WHERE status <> 'finished';
CREATE TABLE IF NOT EXISTS integration_tokens(user_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_sync timestamptz);
CREATE TABLE IF NOT EXISTS articles(id text PRIMARY KEY,title text NOT NULL,url text NOT NULL UNIQUE,source text NOT NULL,summary text NOT NULL DEFAULT '',minutes integer NOT NULL DEFAULT 5 CHECK(minutes BETWEEN 1 AND 120),published_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS daily_reading(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,date date NOT NULL,article_id text NOT NULL REFERENCES articles ON DELETE CASCADE,PRIMARY KEY(user_id,date,article_id));
CREATE TABLE IF NOT EXISTS reading_state(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,article_id text NOT NULL REFERENCES articles ON DELETE CASCADE,read boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS push_subscriptions(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,endpoint text NOT NULL,subscription jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,endpoint));
CREATE TABLE IF NOT EXISTS ai_usage(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,month text NOT NULL,reserved_cents integer NOT NULL DEFAULT 0,PRIMARY KEY(user_id,month));
CREATE TABLE IF NOT EXISTS ai_insights(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,text text NOT NULL,provider text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_runs(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,job text NOT NULL,date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,job,date));
INSERT INTO schema_migrations(version) VALUES('001') ON CONFLICT DO NOTHING;
